  initFunctionMenu() {
    const tabs = document.querySelectorAll('.menu-tab');
    
    tabs.forEach(tab => {
      tab.addEventListener('click', (e) => {
        const targetId = tab.dataset.target;
        
        // 攔截管理員後台分頁
        if (targetId === 'panel-admin' && !this.isAdmin) {
          e.preventDefault();
          this.openAdminPasswordModal();
          return;
        }
        
        this.switchToTab(targetId);
      });
    });

    // 綁定選單左右平滑捲動導覽箭頭按鈕
    const container = document.getElementById('functionMenuContainer');
    const btnLeft = document.getElementById('menuScrollLeft');
    const btnRight = document.getElementById('menuScrollRight');

    if (container && btnLeft && btnRight) {
      const updateScrollButtons = () => {
        const scrollLeft = container.scrollLeft;
        const scrollWidth = container.scrollWidth;
        const clientWidth = container.clientWidth;

        // 若超出現有寬度
        if (scrollWidth > clientWidth + 5) {
          if (scrollLeft > 5) {
            btnLeft.classList.add('visible');
          } else {
            btnLeft.classList.remove('visible');
          }

          if (scrollLeft + clientWidth < scrollWidth - 5) {
            btnRight.classList.add('visible');
          } else {
            btnRight.classList.remove('visible');
          }
        } else {
          btnLeft.classList.remove('visible');
          btnRight.classList.remove('visible');
        }
      };

      btnLeft.addEventListener('click', () => {
        container.scrollBy({ left: -220, behavior: 'smooth' });
      });

      btnRight.addEventListener('click', () => {
        container.scrollBy({ left: 220, behavior: 'smooth' });
      });

      container.addEventListener('scroll', updateScrollButtons);
      window.addEventListener('resize', updateScrollButtons);
      
      // 延遲更新以防瀏覽器與字型動態渲染
      setTimeout(updateScrollButtons, 300);
      setTimeout(updateScrollButtons, 1000);
    }
  }
  
  handleAdminEntryClick() {
    if (this.isAdmin) {
      this.switchToTab('panel-admin');
    } else {
      this.openAdminPasswordModal();
    }
  }

  switchToTab(targetId) {
    // 嚴格安全防護：未登入教師/管理員身分時，禁止切換進入管理後台
    if (targetId === 'panel-admin' && !this.isAdmin) {
      this.openAdminPasswordModal();
      return;
    }

    const fsEl = document.fullscreenElement;
    const targetPanel = document.getElementById(targetId);
    if (fsEl && fsEl !== document.documentElement && targetPanel && !fsEl.contains(targetPanel)) {
      if (document.exitFullscreen) {
        document.exitFullscreen().catch(() => {});
      }
    }

    const tabs = document.querySelectorAll('.menu-tab');
    const panels = document.querySelectorAll('.main-content .panel-card');
    
    tabs.forEach(tab => {
      if (tab.dataset.target === targetId) {
        tab.classList.add('active');
      } else {
        tab.classList.remove('active');
      }
    });
    
    panels.forEach(panel => {
      if (panel.id === targetId) {
        panel.classList.add('active');
      } else {
        panel.classList.remove('active');
      }
    });
    
    // 記錄目前選按的功能選單，供貼上事件判斷用
    this.previousTabId = this.activeTabId;
    this.activeTabId = targetId;
    if (this.isAdmin && typeof this.saveAdminSession === 'function') {
      this.saveAdminSession(targetId === 'panel-admin');
    }

    if (targetId === 'panel-admin' || targetId === 'panel-teacher-shares') {
      const focusOverlay = document.getElementById('focusGameOverlay');
      if (focusOverlay) focusOverlay.style.display = 'none';
      const buzzOverlay = document.getElementById('buzzGameOverlay');
      if (buzzOverlay) buzzOverlay.style.display = 'none';
    }

    if (targetId !== 'panel-video-quiz') {
      if (window.videoQuiz && typeof window.videoQuiz.pauseVideo === 'function') {
        window.videoQuiz.pauseVideo();
      }
    } else {
      if (window.videoQuiz && typeof window.videoQuiz.init === 'function') {
        window.videoQuiz.init();
      }
      if (window.videoQuiz && typeof window.videoQuiz.onTabEnter === 'function') {
        window.videoQuiz.onTabEnter();
      }
    }

    if (targetId === 'panel-quiz') {
      if (window.quiz && typeof window.quiz.setAdminState === 'function') {
        window.quiz.setAdminState(this.isAdmin);
      }
      if (window.quiz && typeof window.quiz.updateUI === 'function') {
        window.quiz.updateUI();
      }
    }

    if (targetId === 'panel-lucky-wheel') {
      this.updateWheelControlPanelVisibility();
      this.applyWheelMode(this.wheelMode || 'wheel', true);
      this.drawWheelLocal();
    } else if (this.isAdmin && this.previousTabId === 'panel-lucky-wheel') {
      const activeRef = db.ref('quiz/luckyWheel/active');
      activeRef.set({ active: false, timestamp: Date.now() });
      activeRef.onDisconnect().cancel();
    }

    if (targetId === 'panel-word-cloud') {
      if (window.wordCloud && typeof window.wordCloud.recalculateAndRender === 'function') {
        setTimeout(() => window.wordCloud.recalculateAndRender(), 60);
      }
      this.updateWheelControlPanelVisibility();
    }

    // 圖片分享與影片分享按需掛載監聽器 (離開封頁即時卸載，零背景流量消耗)
    if (targetId === 'panel-images') {
      this.attachImageSyncListener();
    } else if (targetId !== 'panel-admin') {
      this.detachImageSyncListener();
    }

    if (targetId === 'panel-videos') {
      this.attachVideoSyncListener();
    } else if (targetId !== 'panel-admin') {
      this.detachVideoSyncListener();
    }

    if (targetId === 'panel-presentation' && window.presentationManager?.draft) {
      window.presentationManager.draft.ensureLoaded();
    }

    if (targetId === 'panel-whiteboard') {
      const iframe = document.getElementById('whiteboardFrame');
      if (iframe && iframe.contentWindow) {
        iframe.contentWindow.postMessage({
          type: 'UPDATE_ADMIN_STATUS',
          isAdmin: !!this.isAdmin,
          userName: this.getCurrentUserName() || (this.isAdmin ? '老師' : '同學')
        }, window.location.origin === 'null' ? '*' : window.location.origin);
      }
    }
    
    if (targetId === 'panel-admin') {
      this.adminPreviewingBuzz = false;
      const focusOverlay = document.getElementById('focusGameOverlay');
      if (focusOverlay) {
        focusOverlay.style.display = 'none';
        focusOverlay.classList.remove('active');
      }
      const buzzOverlay = document.getElementById('buzzGameOverlay');
      if (buzzOverlay) {
        buzzOverlay.style.display = 'none';
        buzzOverlay.classList.remove('active');
      }
      const vqOverlay = document.getElementById('vqQuestionOverlay');
      if (vqOverlay) {
        vqOverlay.style.display = 'none';
      }
      if (window.videoQuiz) {
        window.videoQuiz.setAdminState(true);
        window.videoQuiz.updateAdminBroadcastUI(window.videoQuiz.lastSession);
      }
      if (window.quiz && typeof window.quiz.setAdminState === 'function') {
        window.quiz.setAdminState(true);
      }
      this.populateAdminClassAvatarDropdown();
      const vqSection = document.getElementById('adminVideoQuizSection');
      if (vqSection && !vqSection.classList.contains('collapsed') && !this.currentAdminFeatureKey) {
        this.openAdminFeature('quizVideo');
      } else if (!this.currentAdminFeatureKey) {
        this.backToAdminDashboard();
      }
    } else {
      if (this.focusGame) this.handleFocusGameSync(this.focusGame);
      if (this.buzzGame) this.handleBuzzGameSync(this.buzzGame);
    }
    this.updateAdminActiveActivitiesUI();
  }

