function resetAll() {
  // 清除 tldraw 白板畫稿與本機快取
  if (window.app && typeof window.app.clearTldrawWhiteboard === 'function') {
    window.app.clearTldrawWhiteboard();
  }

  // 清除選擇題測驗畫面與結果
  if (window.quiz && typeof window.quiz.clearQuizResults === 'function') {
    window.quiz.clearQuizResults();
  }

  const isOneOff = (window.ClassRoomManager && typeof window.ClassRoomManager.isOneOffClass === 'function')
    ? window.ClassRoomManager.isOneOffClass()
    : !window.currentClassCode;

  const classKey = window.currentClassCode ? `class_${window.currentClassCode}` : 'one_off_root';

  const promises = [
    db.ref('questions').remove(),
    db.ref('attachments').remove(),
    db.ref('quiz/questionFolders').remove(),
    db.ref('quiz/current').remove(),
    db.ref('quiz/answers').remove(),
    db.ref('images').remove(),
    db.ref('quiz/imageFolders').remove(),
    db.ref('videos').remove(),
    db.ref('quiz/videoFolders').remove(),
    db.ref('quiz/broadcastVideo').remove(),
    db.ref('teacherShares').remove(),
    db.ref('quiz/teacherShareFolders').remove(),
    db.ref('quiz/luckyWheel').remove(),
    db.ref('quiz/videoQuizSession').remove(),
    db.ref('quiz/videoQuizSettings').remove(),
    db.ref('quiz/videoQuizAnswers').remove(),
    db.ref('quiz/students').remove(),
    db.ref('student_real_names').remove(),
    db.ref('student_reaction_counts').remove(),
    db.ref('quiz/presence').remove(), // 徹底清除線上連線與快取記錄，避免舊名稱殘留
    db.ref('whiteboard').remove(),
    db.ref('whiteboard_room').remove(),
    db.ref('whiteboard_v2').remove(),
    db.ref('system/quotaStats/classStorageMap').child(classKey).set(0),
    db.ref('quiz/resetTimestamp').set(Date.now()) // 廣播重設事件至所有線上學生端
  ];

  if (isOneOff) {
    // 一次性課堂清除資料時，一併清除本機學生名稱記錄
    window.boardStorage.local.removeItem('user_nickname');
    window.boardStorage.local.removeItem('user_name');
    window.boardStorage.local.removeItem('comment_nickname');
  }

  if (window.app) {
    window.app.registeredStudents = {};
    window.app.onlinePresence = {};
  }

  Promise.all(promises).then(() => {
    if (window.app) window.app.showNotification('成功', '所有資料與學生登入名稱已成功清除重設！');
    setTimeout(() => {
      location.reload();
    }, 500);
  }).catch(err => {
    console.error("Reset failed:", err);
    if (window.app) window.app.showNotification('錯誤', '重設失敗: ' + err.message);
    else alert('重設失敗: ' + err.message);
  });
}

