// 管理員密碼驗證
function closeAdminPasswordModal() {
  window.app.closeAdminPasswordModal();
}

async function submitAdminPassword() {
  const inputEl = document.getElementById('adminPasswordInput');
  const pwd = inputEl ? inputEl.value : '';

  if (window.teacherAuthManager) {
    const res = await window.teacherAuthManager.verifyPassword(pwd);
    if (res.success) {
      window.app.isAdmin = true;
      if (typeof window.app.startAdminIdleMonitor === 'function') {
        window.app.startAdminIdleMonitor();
      }
      if (window.videoQuiz) window.videoQuiz.setAdminState(true);
      if (window.quiz && typeof window.quiz.setAdminState === 'function') window.quiz.setAdminState(true);
      const targetFeature = window.app.pendingAdminFeature;
      window.app.pendingAdminFeature = null;
      window.app.closeAdminPasswordModal(); // 關閉彈窗
      if (targetFeature && typeof window.app.openAdminFeature === 'function') {
        window.app.openAdminFeature(targetFeature);
      } else {
        window.app.switchToTab('panel-admin'); // 自動進入「管理後台」分頁
      }
      window.app.handleFocusGameSync(window.app.focusGame); // 即時更新專注力大廳 UI
      window.app.handleBuzzGameSync(window.app.buzzGame); // 即時更新搶答狀態
      window.app.updateFocusGameAdminOptions();
      window.app.updateAdminActiveActivitiesUI();
  if (typeof window.app.applyFloatingButtonPosition === 'function') {
    window.app.applyFloatingButtonPosition();
  }
      window.app.renderFirebaseQuotaBanners();
      window.app.scheduleCurrentClassStorageSync();
      if (typeof window.app.applyFloatingButtonPosition === 'function') {
        window.app.applyFloatingButtonPosition();
      }

      if (res.isDefault) {
        const days = res.remainingDays !== undefined ? res.remainingDays : (window.teacherAuthManager ? window.teacherAuthManager.getDefaultPasswordRemainingDays() : 0);
        window.app.showNotification('⚠️ 預設密碼即將失效提醒', `已登入管理員！目前仍使用系統預設密碼，新註冊後一週內須設定專屬密碼（寬限期僅剩 ${days} 天）！請儘速至「班級管理 > F. 教師身分與密碼安全設定」修改為專屬密碼。`);
      } else {
        window.app.showNotification('🎉 驗證成功', res.message || '已進入管理員模式！');
      }

      window.app.checkDefaultPasswordBanner();

      if (typeof window.app.checkTimerExpiry === 'function') {
        window.app.checkTimerExpiry();
      }
      if (window.app.timerState) {
        window.app.updateAdminTimerUI(window.app.timerState);
      }
      window.app.checkSecurityRuleExpiry();
    } else {
      window.teacherAuthManager.updatePasswordModalUI();
      // 簡化為單一登入框內紅字提示 + 輸入框搖晃特效，不重複彈出 #notifyModal 阻斷輸入焦點
      const errBox = document.getElementById('adminPasswordErrorMsg');
      if (errBox) {
        errBox.style.display = 'block';
        errBox.innerHTML = res.message || '密碼不正確！';
        errBox.classList.remove('admin-input-shake');
        void errBox.offsetWidth;
        errBox.classList.add('admin-input-shake');
      }
      if (inputEl && !res.locked) {
        inputEl.classList.remove('admin-input-shake');
        void inputEl.offsetWidth;
        inputEl.classList.add('admin-input-shake');
        inputEl.select();
        inputEl.focus();
      }
    }
  } else {
    // 容錯備援舊邏輯
    if (pwd === '1234') {
      if (window.teacherAuthManager && window.teacherAuthManager.isDefaultPasswordExpired()) {
        const errBox = document.getElementById('adminPasswordErrorMsg');
        if (errBox) {
          errBox.style.display = 'block';
          errBox.innerHTML = '⛔ 初始預設密碼已超過一週（7天）寬限期並已失效！請使用專屬密碼或忘記密碼自救。';
        }
        return;
      }
      window.app.isAdmin = true;
      if (typeof window.app.startAdminIdleMonitor === 'function') {
        window.app.startAdminIdleMonitor();
      }
      if (window.videoQuiz) window.videoQuiz.setAdminState(true);
      if (window.quiz && typeof window.quiz.setAdminState === 'function') window.quiz.setAdminState(true);
      const targetFeature = window.app.pendingAdminFeature;
      window.app.pendingAdminFeature = null;
      window.app.closeAdminPasswordModal();
      if (targetFeature && typeof window.app.openAdminFeature === 'function') {
        window.app.openAdminFeature(targetFeature);
      } else {
        window.app.switchToTab('panel-admin');
      }
      window.app.updateAdminActiveActivitiesUI();
  if (typeof window.app.applyFloatingButtonPosition === 'function') {
    window.app.applyFloatingButtonPosition();
  }
      window.app.renderFirebaseQuotaBanners();
      window.app.scheduleCurrentClassStorageSync();
      if (typeof window.app.applyFloatingButtonPosition === 'function') {
        window.app.applyFloatingButtonPosition();
      }
      window.app.showNotification('成功', '已進入管理員模式！');
      window.app.checkDefaultPasswordBanner();
    } else {
      const errBox = document.getElementById('adminPasswordErrorMsg');
      if (errBox) {
        errBox.style.display = 'block';
        errBox.innerHTML = '密碼不正確！';
        errBox.classList.remove('admin-input-shake');
        void errBox.offsetWidth;
        errBox.classList.add('admin-input-shake');
      }
    }
  }
}

function logoutAdmin(isAutoIdleLogout = false) {
  window.app.isAdmin = false;
  if (typeof window.app.clearAdminSession === 'function') {
    window.app.clearAdminSession();
  }
  if (typeof window.app.stopAdminIdleMonitor === 'function') {
    window.app.stopAdminIdleMonitor();
  }
  if (window.videoQuiz) window.videoQuiz.setAdminState(false);
  if (window.quiz && typeof window.quiz.setAdminState === 'function') window.quiz.setAdminState(false);
  window.app.closeAdminPasswordModal();
  window.app.switchToTab('panel-questions'); // 登出後切換回到「提問區分頁」
  window.app.handleFocusGameSync(window.app.focusGame); // 即時更新專注力大廳 UI
  window.app.handleBuzzGameSync(window.app.buzzGame); // 即時更新搶答狀態
  window.app.updateAdminActiveActivitiesUI();
  if (typeof window.app.applyFloatingButtonPosition === 'function') {
    window.app.applyFloatingButtonPosition();
  }

  if (isAutoIdleLogout === true) {
    window.app.showNotification('🔒 安全自動保護', '因管理員模式閒置超過 90 分鐘，系統已自動登出並切回學生視角，防止公用電腦誤觸。');
  } else {
    window.app.showNotification('提示', '已登出管理員模式');
  }
  
  const volBtn = document.getElementById('timerVolumeBtn');
  if (volBtn) volBtn.style.display = 'none';
  window.app.playAudio('none');
  if (window.app && typeof window.app.checkDefaultPasswordBanner === 'function') {
    window.app.checkDefaultPasswordBanner();
  }
}

// ===== 管理員編輯提問（含附件刪除、更換與新增） =====
function adminEditQuestion(id) {
  const textDiv  = document.getElementById('q-text-' + id);
  const editDiv  = document.getElementById('q-edit-' + id);
  if (!textDiv || !editDiv) return;
  textDiv.style.display = 'none';
  editDiv.style.display  = 'block';
  if (window.app && typeof window.app.initAdminQuestionAttachmentEdit === 'function') {
    window.app.initAdminQuestionAttachmentEdit(id);
  }
  const ta = document.getElementById('q-textarea-' + id);
  if (ta) ta.focus();
}
window.app && (window.app.adminEditQuestion = adminEditQuestion);

function adminCancelEditQuestion(id) {
  const textDiv = document.getElementById('q-text-' + id);
  const editDiv = document.getElementById('q-edit-' + id);
  if (textDiv) textDiv.style.display = '';
  if (editDiv) editDiv.style.display = 'none';
  if (window.app && window.app._adminQEditAttState) {
    delete window.app._adminQEditAttState[id];
  }
}
window.app && (window.app.adminCancelEditQuestion = adminCancelEditQuestion);

async function adminSaveQuestion(id) {
  const ta = document.getElementById('q-textarea-' + id);
  if (!ta || !window.app) return;
  const state = window.app._adminQEditAttState ? window.app._adminQEditAttState[id] : null;
  const currentAtt = state ? state.current : null;

  let newText = ta.value.trim();
  if (!newText && currentAtt) {
    const attName = currentAtt.isNew ? currentAtt.staged.name : currentAtt.meta.name;
    newText = `📎 分享附件：${attName}`;
  }
  if (!newText) {
    window.app.showNotification('提示', '問題文字不能為空');
    return;
  }

  const saveBtn = document.getElementById('q-save-btn-' + id);
  try {
    if (saveBtn) {
      saveBtn.disabled = true;
      saveBtn.textContent = '⏳ 儲存中...';
    }

    const updates = { text: newText, updatedAt: firebase.database.ServerValue.TIMESTAMP };
    if (state) {
      const origList = state.original || [];
      if (origList.length > 0 && (!currentAtt || currentAtt.isNew)) {
        window.app.deleteAttachmentsFromDb(origList);
      }
      if (currentAtt) {
        if (currentAtt.isNew) {
          const uploadedMeta = await window.app.uploadAttachmentToDb(currentAtt.staged, 'question');
          updates.attachments = [uploadedMeta];
        } else {
          updates.attachments = [currentAtt.meta];
        }
      } else {
        updates.attachments = null;
      }
    }

    await db.ref('questions').child(id).update(updates);
    window.app.showNotification('成功', '提問與附件已更新！');
    adminCancelEditQuestion(id);
  } catch (err) {
    if (saveBtn) {
      saveBtn.disabled = false;
      saveBtn.textContent = '💾 儲存';
    }
    window.app.showNotification('錯誤', '更新失敗: ' + err.message);
  }
}
